script:
class Component extends DCLogic {
  constructor(props) { super(props); this.state = { open: {}, m: '', staff: [{ id: 's1', name: 'Анна Ким', mail: 'a.kim@peragov.example' }], sName: '', sMail: '', sErr: false, bFile: '', bRows: [], bErr: false, rTopic: 0, rText: '', rErr: false, }; }

  _y(e) { try { const m = document.querySelector('main.kab__main'); return Math.round(e.currentTarget.getBoundingClientRect().top - m.getBoundingClientRect().top); } catch (x) { return 120; } }
  say(msg, e) { const y = this._y(e); this.setState({ toast: msg, toastY: Math.max(8, y + ((e && e.currentTarget && e.currentTarget.offsetHeight) || 40) + 8) }); clearTimeout(this._tt); this._tt = setTimeout(() => this.setState({ toast: '' }), 3800); }

  bParse(text) {
    const rows = text.split(/\r?\n/).map((l) => l.trim()).filter(Boolean).map((l) => l.split(/[;\t,]/).map((c) => c.trim().replace(/^"|"$/g, '')));
    if (rows.length && /^(имя|name)/i.test(rows[0][0] || '')) rows.shift();
    return rows.filter((r) => r[0] && r[1]).map((r) => ({ n: r[0], m: r[1], p: r[2] || '-', r: r[3] || 'Сотрудник' }));
  }
  bPick(e) {
    const f = e.target.files && e.target.files[0]; if (!f) return;
    const sample = [{ n: 'Мария Ли', m: 'm.li@peragov.example', p: '+971 50 111 22 33', r: 'Менеджер' }, { n: 'Тимур Алиев', m: 't.aliev@peragov.example', p: '+971 50 444 55 66', r: 'Ассистент' }, { n: 'Софья Нова', m: 's.nova@peragov.example', p: '-', r: 'Менеджер' }];
    if (/\.csv$/i.test(f.name) && window.FileReader) { const rd = new FileReader(); rd.onload = () => { const r = this.bParse(String(rd.result || '')); this.setState({ bFile: f.name, bRows: r, bErr: false }); }; rd.readAsText(f, 'utf-8'); }
    else this.setState({ bFile: f.name, bRows: sample, bErr: false });
  }
  openM(name, e, extra) { const y = this._y(e); this.setState(Object.assign({ m: name, mTop: Math.max(16, y - 40) }, extra || {})); }
  closeM() { this.setState({ m: '' }); }
  baseVals() {
    const S = this.state;
    return { toastOn: !!S.toast, toast: S.toast || '', toastStyle: 'top:' + (S.toastY || 80) + 'px;width:max-content;max-width:min(420px,calc(100% - 32px))', mOn: !!S.m, ovlStyle: 'padding-top:' + (S.mTop || 24) + 'px',
      closeOvl: (e) => { if (e.target === e.currentTarget) this.closeM(); }, closeBtn: () => this.closeM(),
      helpOpen: (e) => this.openM('help', e), m_help: S.m === 'help' };
  }

  renderVals() {
    const S = this.state, ok = (v) => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v.trim());
    const staffRows = S.staff.map((x) => ({ id: x.id, name: x.name, tag: 'Сотрудник', badge: 'badge--muted', sub: x.mail + (x.role ? ', ' + x.role : ''), det: 'Работает в Вашем кабинете. Деньги и договор остаются за Вами.', open: !!S.open[x.id], pick: () => this.setState({ open: Object.assign({}, S.open, { [x.id]: !S.open[x.id] }) }),
      del: (e) => { this.setState({ staff: S.staff.filter((y) => y.id !== x.id), open: {} }); this.say('Сотрудник убран', e); } }));
    const e3 = S.sErr && !S.sName.trim() ? 'is-err' : '', e4 = S.sErr && !ok(S.sMail) ? 'is-err' : '';
    return Object.assign(this.baseVals(), { bulkOpen: (e) => this.openM('bulk', e, { bFile: '', bRows: [], bErr: false }), m_bulk: S.m === 'bulk',
      bFileName: S.bFile || 'Файл ещё не выбран', bHas: S.bRows.length > 0, bRows: S.bRows.slice(0, 4), bRowsT: 'Всего в файле: ' + S.bRows.length + (S.bRows.length > 4 ? '. Показаны первые 4.' : '.'), bErrCls: S.bErr ? 'is-err' : '',
      bBtn: 'Добавить' + (S.bRows.length ? ' ' + S.bRows.length + (S.bRows.length === 1 ? ' сотрудника' : ' сотрудников') : ' сотрудников'),
      bFile: (e) => this.bPick(e),
      bTpl: (e) => { try { const b = new Blob(['\ufeffИмя;Почта;Телефон;Роль\nАнна Ким;a.kim@example.com;+971 50 000 00 00;Менеджер\n'], { type: 'text/csv' }); const a = document.createElement('a'); a.href = URL.createObjectURL(b); a.download = 'sotrudniki-shablon.csv'; a.click(); } catch (x) {} this.say('Шаблон скачан: заполните и загрузите его', e); },
      bSend: (e) => { if (e && e.preventDefault) e.preventDefault(); if (!S.bRows.length) { this.setState({ bErr: true }); return; } const n = S.bRows.length; this.setState({ m: '', staff: S.staff.concat(S.bRows.map((r, i) => ({ id: 'b' + Date.now() + i, name: r.n, mail: r.m, phone: r.p === '-' ? '' : r.p, role: r.r }))), bRows: [], bFile: '' }); this.say(n === 1 ? 'Сотрудник добавлен' : 'Сотрудники добавлены: ' + n, e); },
      reqOpen: (e) => this.openM('req', e, { rTopic: 0, rText: '', rErr: false }), m_req: S.m === 'req',
      rTopics: ['Добавить сотрудников', 'Права доступа', 'Договор', 'Другое'].map((t, i) => ({ t, on: S.rTopic === i, pick: () => this.setState({ rTopic: i }) })),
      rText: S.rText, rSetText: (e) => this.setState({ rText: e.target.value, rErr: false }), rErrCls: S.rErr ? 'is-err' : '',
      rSend: (e) => { if (e && e.preventDefault) e.preventDefault(); if (!S.rText.trim()) { this.setState({ rErr: true }); return; } this.setState({ m: '', rText: '' }); this.say('Запрос отправлен, ответим в течение рабочего дня', e); },
      staffRows,
      staffOpen: (e) => this.openM('staff', e, { sErr: false, sName: '', sMail: '' }), m_staff: S.m === 'staff',
      sName: S.sName, sMail: S.sMail, sSetName: (e) => this.setState({ sName: e.target.value, sErr: false }), sSetMail: (e) => this.setState({ sMail: e.target.value, sErr: false }),
      sNameErr: e3, sNameErr_e: e3 ? 'Напишите имя' : '', sMailErr: e4, sMailErr_e: e4 ? 'Проверьте почту' : '',
      sSend: (e) => { if (e && e.preventDefault) e.preventDefault(); if (!S.sName.trim() || !ok(S.sMail)) { this.setState({ sErr: true }); return; } this.setState({ m: '', staff: S.staff.concat([{ id: 's' + (S.staff.length + 9), name: S.sName.trim(), mail: S.sMail.trim() }]) }); this.say('Сотрудник добавлен', e); } });
  }
}

Component = (function (Base) { return class extends Base {
  constructor(props) { super(props); if (HB.isNovice()) this.state.staff = []; }
  renderVals() { const v = super.renderVals(); const S = this.state, set = (o) => this.setState(o); v.staffBlank = S.staff.length === 0; return v; }
}; })(Component);
